 <div class="footer"><span>✦ <span id="rate">+4</span> crumbs / sec</span><div class="toggle on" id="auto"><span class="switch"></span><span>Auto-battle</span></div></div>
 <div class="toast" id="toast"></div><div class="shade" id="shade"><div class="modal"><div class="big" id="modalEmoji">🎉</div><h2 id="modalTitle">The chef is safe!</h2><p id="modalText">Another wave of hungry cookies is on the way.</p><button id="continue">Onward, crumbs!</button></div></div>
 </main>
 <script>
+(()=>{'use strict';
+const $=id=>document.getElementById(id);const fresh={crumbs:42,honey:2,wave:1,level:1,kills:0,hp:100,auto:true,sound:false,last:Date.now()};let s={...fresh,...JSON.parse(localStorage.getItem('crumb-save')||'{}')};let enemyMax=80+s.wave*20;let lastAttack=0;let toastTimer;const names=['RIVAL MACARON','DREAD DOUGH','THE ICING KNIGHT','CRUMB COLLECTOR','BARON VON BAKED'];
+function save(){s.last=Date.now();localStorage.setItem('crumb-save',JSON.stringify(s))}
+function showToast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),1700)}
+function fmt(n){return Math.floor(n).toLocaleString()}
+function update(){ $('crumbs').textContent=fmt(s.crumbs);$('honey').textContent=fmt(s.honey);$('wave').textContent=`NIGHT ${String(Math.floor((s.wave-1)/5)+1).padStart(2,'0')} · WAVE ${s.wave}`;$('level').textContent=s.level;$('dmg').textContent=6+s.level*2;$('upgradeCost').textContent=upgradeCost();$('rate').textContent=4+s.level*2;$('enemyName').textContent=names[(s.wave-1)%names.length];$('heroHp').style.setProperty('--hp',`${Math.max(4,100-(s.kills%10)*8)}%`);$('enemyHp').style.setProperty('--hp',`${Math.max(0,s.hp/enemyMax*100)}%`);$('stamina').textContent=`${Math.max(0,Math.ceil(s.hp))} / ${enemyMax}`;$('bar').style.width=`${Math.max(0,s.hp/enemyMax*100)}%`;$('chapter').textContent=s.wave<5?'THE GREAT COOKIE CLASH':s.wave<10?'A VERY CRUMBLY REBELLION':'THE LAST CRUMB STANDING';$('auto').classList.toggle('on',s.auto);$('upgrade').classList.toggle('disabled',s.crumbs<upgradeCost());$('bake').classList.toggle('disabled',s.honey<1)}
+function upgradeCost(){return Math.floor(35*Math.pow(1.48,s.level-1))}
+function hit(amount,manual=false){if(!s.auto&&!manual)return;const enemy=$('enemy');enemy.classList.remove('hit');void enemy.offsetWidth;enemy.classList.add('hit');const slash=document.createElement('div');slash.className='slash';slash.textContent=['✦','⚔','✧','★'][Math.floor(Math.random()*4)];slash.style.left=`${58+Math.random()*20}%`;slash.style.top=`${43+Math.random()*20}%`;$('stage').append(slash);setTimeout(()=>slash.remove(),520);s.hp-=amount;s.crumbs+=1; if(s.hp<=0)winWave();update();save()}
+function winWave(){s.kills++;const reward=18+s.wave*7;s.crumbs+=reward;s.hp=80+s.wave*20;enemyMax=s.hp;$('quest').textContent=`+${reward} crumbs! The chef is still not dinner.`;showToast(`Rival crumbled! +${reward} crumbs`);if(s.wave%3===0){s.honey+=1;showToast(`Rival crumbled! +${reward} crumbs · 🍯 honey!`)}if(s.wave%5===0){$('modalEmoji').textContent='👨‍🍳';$('modalTitle').textContent='The chef is still safe!';$('modalText').textContent=`Wave ${s.wave} survived. The cookie kingdoms unite... temporarily. A bigger rival is coming!`;$('shade').classList.add('open')}}
+$('stage').addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;hit(6+s.level*2,true);const sp=document.createElement('span');sp.className='spark';sp.textContent=['✨','🍪','✦'][Math.floor(Math.random()*3)];sp.style.left=`${e.offsetX}px`;sp.style.top=`${e.offsetY}px`;$('stage').append(sp);setTimeout(()=>sp.remove(),700)});
+$('upgrade').addEventListener('click',()=>{const cost=upgradeCost();if(s.crumbs<cost){showToast(`Need ${cost} crumbs to harden up!`);return}s.crumbs-=cost;s.level++;showToast(`Crust hardened! Crew power +4`);update();save()});
+$('bake').addEventListener('click',()=>{if(s.honey<1){showToast('No honey! Defeat rivals to earn more.');return}s.honey--;hit(55+s.level*12,true);showToast('SWEET AMBUSH! 🍯');update();save()});
+$('auto').addEventListener('click',()=>{s.auto=!s.auto;showToast(s.auto?'Crew on auto-battle!':'Auto-battle paused · tap to fight!');update();save()});$('continue').addEventListener('click',()=>{$('shade').classList.remove('open');$('quest').textContent='Protect the chef. Don\'t become dessert.'});
+// Idle income and the crew's steady automatic attacks.
+setInterval(()=>{s.crumbs+=4+s.level*2;if(s.auto)hit(6+s.level*2);else{update();save()}},1000);
+// A modest offline allowance, capped so returning never skips the game.
+const elapsed=Math.min(8*60*60,Math.max(0,(Date.now()-(s.last||Date.now()))/1000));if(elapsed>15){const bonus=Math.floor(elapsed*(4+s.level*2));s.crumbs+=bonus;setTimeout(()=>showToast(`While away, your crew found ${fmt(bonus)} crumbs!`),550)}
+update();save();
+})();
+</script></body></html>

